<?php $title='Benachrichtigungsregeln';$roleLabels=['employee'=>'Mitarbeiter','management'=>'Leitung','admin'=>'Admin']; ?>
<div class="page-header"><div><p class="eyebrow">Administration · Benachrichtigungen</p><h1>Ereignisregeln</h1><p>Interne Hinweise und Standort-E-Mails werden getrennt gesteuert. E-Mail ist standardmäßig deaktiviert und zusätzlich vom globalen Mail-Schalter abhängig.</p></div></div>
<div class="notice warning"><strong>Mail-Sicherheitsstufe:</strong> Eine aktivierte E-Mail-Regel versendet nur dann tatsächlich, wenn zusätzlich der globale Mailversand und der Mailmodus des Standorts freigegeben sind.</div>
<div class="panel"><h2>Vorhandene Regeln</h2><?php foreach($rules as $r):?><form method="post" action="<?= e(url('admin/notifications/rule')) ?>" class="compact-form"><?= csrf_field() ?><input type="hidden" name="id" value="<?= (int)$r['id'] ?>"><label>Ereignis<select name="event_code"><?php foreach($events as $code=>$name):?><option value="<?= e($code) ?>" <?= $r['event_code']===$code?'selected':'' ?>><?= e($name) ?></option><?php endforeach;?></select></label><label>Rolle<select name="role_code"><option value="">Alle Rollen</option><?php foreach($roleLabels as $code=>$name):?><option value="<?= e($code) ?>" <?= $r['role_code']===$code?'selected':'' ?>><?= e($name) ?></option><?php endforeach;?></select></label><label>Standort<select name="location_id"><option value="">Alle Standorte</option><?php foreach($locations as $l):?><option value="<?= (int)$l['id'] ?>" <?= (int)$r['location_id']===(int)$l['id']?'selected':'' ?>><?= e($l['name']) ?></option><?php endforeach;?></select></label><label class="check-row"><input type="checkbox" name="internal_enabled" value="1" <?= $r['internal_enabled']?'checked':'' ?>><span>Intern</span></label><label class="check-row"><input type="checkbox" name="email_enabled" value="1" <?= $r['email_enabled']?'checked':'' ?>><span>Standort-E-Mail</span></label><label class="check-row"><input type="checkbox" name="active" value="1" <?= $r['active']?'checked':'' ?>><span>Aktiv</span></label><button class="button secondary" type="submit">Speichern</button></form><?php endforeach;?></div>
<div class="panel"><h2>Neue Regel</h2><form method="post" action="<?= e(url('admin/notifications/rule')) ?>" class="compact-form"><?= csrf_field() ?><label>Ereignis<select name="event_code"><?php foreach($events as $code=>$name):?><option value="<?= e($code) ?>"><?= e($name) ?></option><?php endforeach;?></select></label><label>Rolle<select name="role_code"><option value="">Alle Rollen</option><?php foreach($roleLabels as $code=>$name):?><option value="<?= e($code) ?>"><?= e($name) ?></option><?php endforeach;?></select></label><label>Standort<select name="location_id"><option value="">Alle Standorte</option><?php foreach($locations as $l):?><option value="<?= (int)$l['id'] ?>"><?= e($l['name']) ?></option><?php endforeach;?></select></label><label class="check-row"><input type="checkbox" name="internal_enabled" value="1" checked><span>Intern</span></label><label class="check-row"><input type="checkbox" name="email_enabled" value="1"><span>Standort-E-Mail</span></label><label class="check-row"><input type="checkbox" name="active" value="1" checked><span>Aktiv</span></label><button class="button primary" type="submit">Regel anlegen</button></form></div>
